CREATE TABLE payroll_templates(id TEXT PRIMARY KEY,school_id TEXT NOT NULL REFERENCES schools(id),name TEXT NOT NULL,heads_json TEXT NOT NULL CHECK(json_valid(heads_json)),rounding TEXT NOT NULL CHECK(rounding IN ('floor','half_up')),rounding_step_minor INTEGER NOT NULL CHECK(rounding_step_minor BETWEEN 1 AND 10000),currency TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,archived_at INTEGER,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(school_id,name),UNIQUE(school_id,id));
CREATE TABLE payroll_structures(id TEXT PRIMARY KEY,school_id TEXT NOT NULL REFERENCES schools(id),user_id TEXT NOT NULL REFERENCES users(id),template_id TEXT NOT NULL,effective_date TEXT NOT NULL,gross_minor INTEGER NOT NULL CHECK(gross_minor BETWEEN 0 AND 1000000000000),amounts_json TEXT NOT NULL CHECK(json_valid(amounts_json)),comments TEXT,version INTEGER NOT NULL DEFAULT 1,archived_at INTEGER,created_by TEXT NOT NULL REFERENCES users(id),FOREIGN KEY(school_id,template_id) REFERENCES payroll_templates(school_id,id),UNIQUE(school_id,user_id,effective_date),UNIQUE(school_id,id));
CREATE TABLE payroll_payslips(id TEXT PRIMARY KEY,school_id TEXT NOT NULL REFERENCES schools(id),structure_id TEXT NOT NULL,user_id TEXT NOT NULL REFERENCES users(id),payslip_no TEXT NOT NULL,starts_on TEXT NOT NULL,ends_on TEXT NOT NULL,days INTEGER NOT NULL CHECK(days BETWEEN 1 AND 366),paid_days INTEGER NOT NULL CHECK(paid_days BETWEEN 0 AND days),currency TEXT NOT NULL,snapshot_json TEXT NOT NULL CHECK(json_valid(snapshot_json)),earnings_minor INTEGER NOT NULL CHECK(earnings_minor>=0),deductions_minor INTEGER NOT NULL CHECK(deductions_minor>=0 AND deductions_minor<=earnings_minor),employer_cost_minor INTEGER NOT NULL CHECK(employer_cost_minor>=0),net_minor INTEGER NOT NULL CHECK(net_minor=earnings_minor-deductions_minor),paid_minor INTEGER NOT NULL DEFAULT 0 CHECK(paid_minor BETWEEN 0 AND net_minor),status TEXT NOT NULL CHECK(status IN ('draft','published','void')),version INTEGER NOT NULL DEFAULT 1,created_by TEXT NOT NULL REFERENCES users(id),created_at INTEGER NOT NULL DEFAULT(unixepoch()),published_at INTEGER,void_reason TEXT,voided_at INTEGER,FOREIGN KEY(school_id,structure_id) REFERENCES payroll_structures(school_id,id),UNIQUE(school_id,payslip_no),UNIQUE(school_id,id),CHECK(starts_on<=ends_on));
CREATE TABLE payroll_payments(id TEXT PRIMARY KEY,school_id TEXT NOT NULL REFERENCES schools(id),payslip_id TEXT NOT NULL,amount_minor INTEGER NOT NULL CHECK(amount_minor!=0),transaction_date TEXT NOT NULL,method TEXT NOT NULL CHECK(method IN ('cash','bank','cheque','upi')),reference TEXT,account_name TEXT NOT NULL,reason TEXT NOT NULL,reverses_id TEXT REFERENCES payroll_payments(id),created_by TEXT NOT NULL REFERENCES users(id),created_at INTEGER NOT NULL DEFAULT(unixepoch()),FOREIGN KEY(school_id,payslip_id) REFERENCES payroll_payslips(school_id,id),CHECK((amount_minor>0 AND reverses_id IS NULL) OR (amount_minor<0 AND reverses_id IS NOT NULL)),UNIQUE(school_id,reverses_id));
CREATE INDEX payroll_employee_period ON payroll_payslips(school_id,user_id,starts_on,ends_on,status);
CREATE INDEX payroll_employee_structures ON payroll_structures(school_id,user_id,effective_date);
CREATE TRIGGER payroll_template_tenant BEFORE INSERT ON payroll_templates WHEN NOT EXISTS(SELECT 1 FROM users WHERE school_id=NEW.school_id AND id=NEW.created_by AND user_type='admin') BEGIN SELECT RAISE(ABORT,'TENANT_RELATIONSHIP'); END;
CREATE TRIGGER payroll_template_locked BEFORE UPDATE ON payroll_templates WHEN NEW.school_id!=OLD.school_id OR NEW.created_by!=OLD.created_by OR (EXISTS(SELECT 1 FROM payroll_structures WHERE school_id=OLD.school_id AND template_id=OLD.id) AND (NEW.heads_json!=OLD.heads_json OR NEW.rounding!=OLD.rounding OR NEW.rounding_step_minor!=OLD.rounding_step_minor OR NEW.currency!=OLD.currency)) BEGIN SELECT RAISE(ABORT,'LOCKED_PAY_TEMPLATE'); END;
CREATE TRIGGER payroll_structure_tenant BEFORE INSERT ON payroll_structures WHEN NOT EXISTS(SELECT 1 FROM users u WHERE u.school_id=NEW.school_id AND u.id=NEW.user_id AND u.user_type IN ('teacher','staff') AND (EXISTS(SELECT 1 FROM teachers WHERE school_id=u.school_id AND user_id=u.id) OR EXISTS(SELECT 1 FROM staff_profiles WHERE school_id=u.school_id AND user_id=u.id))) OR NOT EXISTS(SELECT 1 FROM users WHERE school_id=NEW.school_id AND id=NEW.created_by AND user_type='admin') BEGIN SELECT RAISE(ABORT,'TENANT_RELATIONSHIP'); END;
CREATE TRIGGER payroll_structure_locked BEFORE UPDATE ON payroll_structures WHEN NEW.school_id!=OLD.school_id OR NEW.user_id!=OLD.user_id OR NEW.created_by!=OLD.created_by OR (EXISTS(SELECT 1 FROM payroll_payslips WHERE school_id=OLD.school_id AND structure_id=OLD.id) AND (NEW.template_id!=OLD.template_id OR NEW.effective_date!=OLD.effective_date OR NEW.gross_minor!=OLD.gross_minor OR NEW.amounts_json!=OLD.amounts_json)) BEGIN SELECT RAISE(ABORT,'LOCKED_PAY_STRUCTURE'); END;
CREATE TRIGGER payslip_tenant BEFORE INSERT ON payroll_payslips WHEN NOT EXISTS(SELECT 1 FROM payroll_structures WHERE school_id=NEW.school_id AND id=NEW.structure_id AND user_id=NEW.user_id) OR NOT EXISTS(SELECT 1 FROM users WHERE school_id=NEW.school_id AND id=NEW.created_by AND user_type='admin') BEGIN SELECT RAISE(ABORT,'TENANT_RELATIONSHIP'); END;
CREATE TRIGGER payslip_immutable BEFORE UPDATE ON payroll_payslips WHEN NEW.school_id!=OLD.school_id OR NEW.structure_id!=OLD.structure_id OR NEW.user_id!=OLD.user_id OR NEW.payslip_no!=OLD.payslip_no OR NEW.starts_on!=OLD.starts_on OR NEW.ends_on!=OLD.ends_on OR NEW.days!=OLD.days OR NEW.paid_days!=OLD.paid_days OR NEW.currency!=OLD.currency OR NEW.snapshot_json!=OLD.snapshot_json OR NEW.earnings_minor!=OLD.earnings_minor OR NEW.deductions_minor!=OLD.deductions_minor OR NEW.employer_cost_minor!=OLD.employer_cost_minor OR NEW.net_minor!=OLD.net_minor OR NEW.created_by!=OLD.created_by OR NEW.created_at!=OLD.created_at OR (OLD.status='void' AND NEW.status!='void') OR (OLD.status='published' AND NEW.status='draft') OR (OLD.published_at IS NOT NULL AND NEW.published_at IS NOT OLD.published_at) BEGIN SELECT RAISE(ABORT,'IMMUTABLE_PAYSLIP'); END;
CREATE TRIGGER payslip_no_delete BEFORE DELETE ON payroll_payslips BEGIN SELECT RAISE(ABORT,'IMMUTABLE_PAYSLIP'); END;
CREATE TRIGGER pay_ledger_tenant BEFORE INSERT ON payroll_payments WHEN NOT EXISTS(SELECT 1 FROM users WHERE school_id=NEW.school_id AND id=NEW.created_by AND user_type='admin') OR (NEW.reverses_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM payroll_payments WHERE school_id=NEW.school_id AND id=NEW.reverses_id AND payslip_id=NEW.payslip_id AND amount_minor=-NEW.amount_minor AND reverses_id IS NULL)) BEGIN SELECT RAISE(ABORT,'TENANT_RELATIONSHIP'); END;
CREATE TRIGGER pay_ledger_no_update BEFORE UPDATE ON payroll_payments BEGIN SELECT RAISE(ABORT,'IMMUTABLE_PAY_LEDGER'); END;
CREATE TRIGGER pay_ledger_no_delete BEFORE DELETE ON payroll_payments BEGIN SELECT RAISE(ABORT,'IMMUTABLE_PAY_LEDGER'); END;
